"use client";
import { ArtemisScope } from "./artemis-scope";
import type { ArtemisLogoCloudContent } from "./components/logo-cloud/content";
import View3 from "./components/logo-cloud/variants/04-carousel";
const variants = {"carousel":View3};
export type { ArtemisLogoCloudContent, ArtemisLogoCloudLogo } from "./components/logo-cloud/content";
export interface ArtemisLogoCloudProps { className?: string; variant?: "carousel"; /** The words on the logo cloud; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisLogoCloudContent>; }
export function ArtemisLogoCloud({ className, variant = "carousel", content }: ArtemisLogoCloudProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View content={content}/></div></ArtemisScope>;}

// @zeus-internal
import type { ComponentType } from "react";

/** One logo in the cloud. */
export interface ArtemisLogoCloudLogo {
  /**
   * The company's name, shown beside the icon. All layouts; carousel also lists every name for screen readers.
   * Keep names unique, since grid, columns and carousel tell logos apart by name.
   */
  name: string;
  /** A logo image shown in place of the icon and name, sized to the row; its alt text names the logo. All layouts. */
  image?: { src: string; alt: string };
  /** The icon beside the name. All layouts, which keep their own icon for that slot when you leave this out. */
  icon?: ComponentType<{ className?: string }>;
}

/** The words on an Artemis logo cloud. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisLogoCloudContent {
  /** A small label over the headline. columns and carousel. */
  badge?: string;
  /** The heading. All layouts; marquee shows it as a small line over the logos. */
  headline: string;
  /** A line under or beside the headline. grid, columns and carousel. */
  subhead?: string;
  /**
   * The logos. All layouts: marquee scrolls them in one row, grid rolls them through eight cells, columns deals them
   * into four scrolling lanes and carousel turns them through two or four slots. Twelve look best; grid needs more
   * than eight to roll.
   */
  logos: ArtemisLogoCloudLogo[];
}

"use client";
// @zeus-internal
import type { ArtemisLogoCloudContent } from "../content";
import { defaultLogos } from "./04-carousel/logos";
import { LogosCarousel } from "./04-carousel/logos-carousel";
const DEFAULT = {
    badge: "Chosen by focused teams",
    headline: "The names change. The standard stays high.",
    subhead: "A rotating view of the teams using one flexible system to ship distinctly their own.",
    logos: defaultLogos,
} satisfies ArtemisLogoCloudContent;
export default function LogoCloudCarousel({ content }: { content?: Partial<ArtemisLogoCloudContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const brandList = copy.logos.map((b) => b.name).join(", ");
    return (<section className="art:w-full art:bg-background art:px-4 art:py-20 art:@min-[640px]/artemis:px-8">
      <div className="art:mx-auto art:w-full art:max-w-6xl">
        <div className="art:grid art:gap-6 art:pb-10 art:@min-[640px]/artemis:grid-cols-[minmax(0,1fr)_minmax(16rem,0.65fr)] art:@min-[640px]/artemis:items-end">
          <div>
            <p className="art:font-medium art:text-muted-foreground art:text-xs art:uppercase art:tracking-[0.16em]">{copy.badge}</p>
            <h2 className="art:mt-4 art:max-w-2xl art:text-balance art:text-foreground art:leading-tight art:tracking-[-0.04em] art:text-4xl art:font-medium">
              {copy.headline}
            </h2>
          </div>
          <p className="art:max-w-md art:text-pretty art:text-muted-foreground art:text-sm art:leading-7 art:@min-[640px]/artemis:justify-self-end">
            {copy.subhead}
          </p>
        </div>
        <div>
          <span className="art:sr-only">{brandList}</span>
          <div className="art:@min-[640px]/artemis:hidden">
            <LogosCarousel columns={2} logos={copy.logos}/>
          </div>
          <div className="art:hidden art:@min-[640px]/artemis:block">
            <LogosCarousel columns={4} logos={copy.logos}/>
          </div>
        </div>
      </div>
    </section>);
}

"use client";
// @zeus-internal
import { AnimatePresence, motion, useInView } from "motion/react";
import { useEffect, useRef, useState } from "react";
import type { ArtemisLogoCloudLogo } from "../../content";
import { BrandMark } from "./logos";
const STEP_MS = 1600;
const IN_VIEW_MARGIN = "100px";
const EASE_OUT_QUAD = [0.25, 0.46, 0.45, 0.94] as const;
const DURATION = 0.5;
const COLUMN_STAGGER = 0.125;
function usePageVisible(): boolean {
    const [visible, setVisible] = useState(true);
    useEffect(() => {
        const update = () => setVisible(document.visibilityState !== "hidden");
        update();
        document.addEventListener("visibilitychange", update);
        return () => document.removeEventListener("visibilitychange", update);
    }, []);
    return visible;
}
export function LogosCarousel({ columns, logos }: {
    columns: number;
    logos: ArtemisLogoCloudLogo[];
}) {
    const ref = useRef<HTMLDivElement>(null);
    const inView = useInView(ref, { margin: IN_VIEW_MARGIN });
    const pageVisible = usePageVisible();
    const [step, setStep] = useState(0);
    const running = inView && pageVisible;
    useEffect(() => {
        if (!running)
            return;
        const id = window.setInterval(() => setStep((s) => s + 1), STEP_MS);
        return () => window.clearInterval(id);
    }, [running]);
    const template = { gridTemplateColumns: `repeat(${columns}, minmax(0, 1fr))` };
    const slots = Array.from({ length: columns }, (_, i) => i);
    return (<div aria-hidden="true" className="art:relative art:flex art:h-28 art:items-center art:border art:border-border">
      <div className="art:pointer-events-none art:absolute art:inset-0 art:grid" style={template}>
        {slots.map((i) => (<span key={i} className="art:border-border art:border-r art:last:border-r-0"/>))}
      </div>
      <div ref={ref} className="art:grid art:relative art:z-10 art:w-full" data-slot="logos-carousel" style={template}>
        {slots.map((i) => {
            const slot = (step * columns + i) % logos.length;
            const brand = logos[slot];
            const transition = { duration: DURATION, ease: EASE_OUT_QUAD, delay: i * COLUMN_STAGGER };
            return (<div key={i} className="art:relative art:overflow-hidden" data-slot="logos-carousel-column">
              <div aria-hidden="true" className="art:pointer-events-none art:invisible art:select-none">
                <BrandMark brand={logos[i % logos.length]} slot={i % logos.length}/>
              </div>
              <AnimatePresence initial={false}>
                <motion.div key={brand.name} className="art:absolute art:inset-0 art:flex art:items-center art:justify-center" data-slot="logos-carousel-logo" initial={{ opacity: 0, y: "60%" }} animate={{ opacity: 1, y: "0%" }} exit={{ opacity: 0, y: "-60%" }} transition={transition}>
                  <BrandMark brand={brand} slot={slot}/>
                </motion.div>
              </AnimatePresence>
            </div>);
        })}
      </div>
    </div>);
}

