import { Aperture, Atom, Box, Circle, Command, createLucideIcon, Diamond, Gem, Hexagon, Octagon, Orbit, Triangle, } from "lucide-react";
import type { ComponentType } from "react";
import type { ArtemisLogoCloudLogo } from "../../content";
const Layers = createLucideIcon("layers", [
    [
        "path",
        {
            d: "M12.83 2.18a2 2 0 0 0-1.66 0L2.6 6.08a1 1 0 0 0 0 1.83l8.58 3.91a2 2 0 0 0 1.66 0l8.58-3.9a1 1 0 0 0 0-1.83z",
            key: "zw3jo",
        },
    ],
    ["path", { d: "M2 12a1 1 0 0 0 .58.91l8.6 3.91a2 2 0 0 0 1.65 0l8.58-3.9A1 1 0 0 0 22 12", key: "1wduqc" }],
    ["path", { d: "M2 17a1 1 0 0 0 .58.91l8.6 3.91a2 2 0 0 0 1.65 0l8.58-3.9A1 1 0 0 0 22 17", key: "kqbvx6" }],
]);
/** The logos the carousel shows when it is given none. */
export const defaultLogos: ArtemisLogoCloudLogo[] = [
    { name: "Workspace" },
    { name: "Group A" },
    { name: "Group B" },
    { name: "Group C" },
    { name: "Group D" },
    { name: "Group E" },
    { name: "Group F" },
    { name: "Group G" },
    { name: "Group H" },
    { name: "Group I" },
    { name: "Group J" },
    { name: "Group K" },
];
/** The icon for each slot, for logos that come without one. */
const ICONS = [Hexagon, Triangle, Aperture, Box, Gem, Command, Octagon, Circle, Diamond, Layers, Atom, Orbit];
export function BrandMark({ brand, slot }: {
    brand: ArtemisLogoCloudLogo;
    slot: number;
}) {
    const Icon: ComponentType<{ className?: string; strokeWidth?: number }> = brand.icon ?? ICONS[slot % ICONS.length];
    return (<span className="art:inline-flex art:min-w-0 art:items-center art:gap-2.5 art:text-muted-foreground">
      {brand.image ? <img src={brand.image.src} alt={brand.image.alt} className="art:h-6 art:w-auto art:max-w-full art:object-contain art:@min-[640px]/artemis:h-7"/> : <>
      <Icon strokeWidth={1.75} className="art:shrink-0 art:size-5 art:@min-[640px]/artemis:size-6" aria-hidden="true"/>
      <span className="art:truncate art:font-semibold art:tracking-tight art:text-base art:@min-[640px]/artemis:text-lg">{brand.name}</span>
      </>}
    </span>);
}
